# Code generated by Claude
"""
Measurement only (David, 2026-10-28, item 1b): the gap between the commanded and the measured joints of the left arm at the PICK UP to PLACE OVER boundary and through the first seconds of PLACE OVER.

    python experiments/comp_gap_report.py DIR [DIR ...]      (DIR = a data/arm_motion/comp/<name> written by experiments/comp_measure.py; numpy only, no simulation)

Two commands are compared with the measured joints: "ctrl" = the position actuator's ctrl as the physics gets it (the skill's command PLUS the gravity feedforward tau_ff / kp, the quantity
earlier reports used: 0.09 to 0.11 rad at joints 1, 4, 7), and "cmd" = the skill's own command before the feedforward (the recorded ctrl). At rest the servo force is kp (ctrl - q), so ctrl - q
is always (the torque holding the arm and the load) / kp, compensated or not; cmd - q is what the feedforward does NOT cover (the sag).
"""
import json
import sys
from pathlib import Path

import numpy as np

np.set_printoptions(precision=3, suppress=True, linewidth=170)
for d in sys.argv[1:]:
    d = Path(d)
    L, P = np.load(d / "left_arm.npz"), np.load(d / "pad_beaker.npz")
    ph = json.loads((d / "phases.json").read_text())
    a = next(p["tick"] for p in ph if "PLACE: OVER" in p["key"])
    spt = int(L["steps_per_tick"])
    q, ctrl, cmd = L["q"], L["cmd"], P["cmd_pre"].reshape(-1, 7)
    print(f"== {d.name}")
    for label, k0, k1 in (("boundary (last step before PLACE OVER)", a * spt - 1, a * spt), ("first 0.5 s of PLACE OVER (largest |gap|)", a * spt, a * spt + 75 * spt),
                           ("first 1.0 s of PLACE OVER (largest |gap|)", a * spt, a * spt + 150 * spt), ("1.0 s to 2.0 s of PLACE OVER (largest |gap|)", a * spt + 150 * spt, a * spt + 300 * spt)):
        for name, c in (("ctrl - q (with feedforward)", ctrl), ("cmd - q (skill command)", cmd)):
            g = c[k0:k1] - q[k0:k1]
            v = g[0] if k1 - k0 == 1 else g[np.abs(g).argmax(axis=0), range(7)]
            print(f"  {label:45s} {name:28s} joints 1..7 {v}   max {np.abs(v).max():.3f}   J1 {v[0]:+.3f} J4 {v[3]:+.3f} J7 {v[6]:+.3f}")
